SELECT Customer.FirstName, Customer.LastName, Employee.City
  FROM Customer
  JOIN Employee ON Customer.SupportRepId = Employee.EmployeeId;

SELECT e1.LastName AS EmployeeName, e2.FirstName AS ReportingEmployeeFirstName
  FROM Employee e1
  JOIN Employee e2 ON e1.ReportsTo = e2.EmployeeId;

SELECT Invoice.BillingCountry, SUM(Invoice.Total) as TotalInvoiceAmount
  FROM Invoice
  GROUP BY Invoice.BillingCountry;

SELECT Name FROM Artist
  LEFT JOIN Album ON Artist.ArtistId = Album.ArtistId
  WHERE Album.AlbumId IS NULL;

SELECT c.FirstName, c.LastName, e.City
FROM Customer c
LEFT JOIN Employee e ON c.SupportRepId = e.EmployeeId;

SELECT t.Name AS TrackName, m.Name AS MediaTypeName
FROM Track t
JOIN MediaType m ON t.MediaTypeId = m.MediaTypeId;

SELECT e1.LastName || ' ' || e1.FirstName AS EmployeeName, e2.FirstName AS ManagerFirstName
FROM Employee e1
JOIN Employee e2 ON e1.ReportsTo = e2.EmployeeId;

SELECT c.FirstName, c.LastName, e.City
FROM Customer AS c
JOIN Employee AS e ON c.SupportRepId = e.EmployeeId;

SELECT Track.Name AS TrackName, MediaType.Name AS MediaTypeName
FROM Track
JOIN MediaType ON Track.MediaTypeId = MediaType.MediaTypeId;

SELECT e.FirstName || ' ' || e.LastName AS EmployeeName, m.FirstName AS ManagerFirstName
